"""Cart pricing."""

import re

from cart.models import Line, Totals

_PERCENT_COUPON = re.compile(r"PERCENT:([0-9]+)")
_FIXED_COUPON = re.compile(r"FIXED:([0-9]+)")


def _percent_of(amount: int, percent: int) -> int:
    """Return `percent`% of `amount` in whole cents, halves rounding up."""
    return (amount * percent + 50) // 100


def price_cart(lines: list[Line], coupon: str | None = None) -> Totals:
    """Price a cart. See README.md for the discount rules."""
    subtotal = 0
    bulk_discount = 0
    for line in lines:
        if line.qty < 1:
            raise ValueError(f"quantity must be at least 1, got {line.qty}")
        if line.unit_cents < 0:
            raise ValueError(f"unit price must not be negative, got {line.unit_cents}")
        amount = line.unit_cents * line.qty
        subtotal += amount
        if line.qty >= 10:
            bulk_discount += _percent_of(amount, 10)

    remaining = subtotal - bulk_discount
    coupon_discount = 0
    if coupon is not None:
        percent_match = _PERCENT_COUPON.fullmatch(coupon)
        if percent_match:
            percent = int(percent_match.group(1))
            if not 1 <= percent <= 100:
                raise ValueError(f"percentage must be in 1..100, got {percent}")
            coupon_discount = _percent_of(remaining, percent)
        else:
            fixed_match = _FIXED_COUPON.fullmatch(coupon)
            if not fixed_match:
                raise ValueError(f"unknown coupon form: {coupon!r}")
            coupon_discount = min(int(fixed_match.group(1)), remaining)

    discount = bulk_discount + coupon_discount
    return Totals(subtotal, discount, subtotal - discount)
